; OSCA maths unit test (generated by the session's script; expected values from signed_scale: bits 29..14 of table[index] * multiplier)
; 32 cases through the memory registers ($20A index, $208/$209 multiplier, $704/$705 result) and again through the ports ($2A, $28/$29).
; Result in palette entry 0: green = no error, red = errors (blue nibble = number of wrong bytes, max 15).
		org 0x5000
start:		di
		ld sp,0x4FF0
		xor a
		out (0x0b),a
		ld hl,0x0000
		ld (hl),0x88
		inc hl
		ld (hl),0x08
		ld hl,table
		ld de,0x0600
		ld bc,512
		ldir				; the maths table (write only at $600-$7FF)
		ld ix,vectors
		ld b,32
		ld c,0
mloop:		ld a,(ix+0)
		ld (0x020A),a
		ld a,(ix+1)
		ld (0x0208),a
		ld a,(ix+2)
		ld (0x0209),a
		nop
		nop
		ld a,(0x0704)
		cp (ix+3)
		jr z,m1
		inc c
m1:		ld a,(0x0705)
		cp (ix+4)
		jr z,m2
		inc c
m2:		ld a,(ix+0)
		out (0x2a),a
		ld a,(ix+1)
		out (0x28),a
		ld a,(ix+2)
		out (0x29),a
		nop
		nop
		in a,(0x28)
		cp (ix+3)
		jr z,m3
		inc c
m3:		in a,(0x29)
		cp (ix+4)
		jr z,m4
		inc c
m4:		ld de,5
		add ix,de
		djnz mloop
		ld a,c
		or a
		jr nz,bad
		ld hl,0x0000
		ld (hl),0xF0
		inc hl
		ld (hl),0x00
		jr idle
bad:		cp 16
		jr c,b1
		ld a,15
b1:		ld hl,0x0000
		ld (hl),a
		inc hl
		ld (hl),0x0F
idle:		jr idle
